'use strict';

// MODULES //

var tape = require( 'tape' );
var array = require( '@stdlib/ndarray/array' );
var zeros = require( '@stdlib/ndarray/zeros' );
var isDataSetArray = require( '@stdlib/plot/vega/base/assert/is-dataset-array' );
var columns2tidy = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof columns2tidy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns an array of data sets', function test( t ) {
	var out = columns2tidy( array( [ [ 1, 2 ], [ 3, 4 ] ] ), [ 'series1', 'series2' ], [ 'index', 'value' ] );
	t.strictEqual( isDataSetArray( out ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns data sets having specified names', function test( t ) {
	var out = columns2tidy( array( [ [ 1, 2 ], [ 3, 4 ] ] ), [ 'beep', 'boop' ], [ 'index', 'value' ] );
	t.strictEqual( out[ 0 ].name, 'beep', 'returns expected value' );
	t.strictEqual( out[ 1 ].name, 'boop', 'returns expected value' );
	t.end();
});

tape( 'the function converts the columns of a two-dimensional ndarray to "tidy" data sets', function test( t ) {
	var expected;
	var actual;
	var out;
	var i;
	var j;

	out = columns2tidy( array( [ [ 1, 2 ], [ 3, 4 ], [ 5, 6 ] ] ), [ 'series1', 'series2' ], [ 'index', 'value' ] );
	actual = [];
	for ( i = 0; i < out.length; i++ ) {
		actual.push( out[ i ].toJSON().values );
		for ( j = 0; j < actual[ i ].length; j++ ) {
			actual[ i ][ j ] = actual[ i ][ j ].toJSON();
		}
	}
	expected = [
		[
			{
				'index': 0,
				'value': 1
			},
			{
				'index': 1,
				'value': 3
			},
			{
				'index': 2,
				'value': 5
			}
		],
		[
			{
				'index': 0,
				'value': 2
			},
			{
				'index': 1,
				'value': 4
			},
			{
				'index': 2,
				'value': 6
			}
		]
	];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports specifying field names', function test( t ) {
	var expected;
	var actual;
	var out;
	var i;
	var j;

	out = columns2tidy( array( [ [ 1, 2 ], [ 3, 4 ] ] ), [ 'series1', 'series2' ], [ 'x', 'y' ] );
	actual = [];
	for ( i = 0; i < out.length; i++ ) {
		actual.push( out[ i ].toJSON().values );
		for ( j = 0; j < actual[ i ].length; j++ ) {
			actual[ i ][ j ] = actual[ i ][ j ].toJSON();
		}
	}
	expected = [
		[
			{
				'x': 0,
				'y': 1
			},
			{
				'x': 1,
				'y': 3
			}
		],
		[
			{
				'x': 0,
				'y': 2
			},
			{
				'x': 1,
				'y': 4
			}
		]
	];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function returns an empty array if provided a two-dimensional ndarray having no columns', function test( t ) {
	var expected;
	var actual;

	actual = columns2tidy( zeros( [ 2, 0 ] ), [], [ 'index', 'value' ] );
	expected = [];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});
